scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

scripts.吕文才死亡.txt:
// 吕文才死亡

	Add($fight016, 1);
	If ($fight016 == 23) @finished;
    Return;
    
@finished:
	StopMusic();
	ClearEffect();
	Say("宋兵：不好了！杀人了！吕将军被人杀了！快跑呀！", 0);
	PlayMusic("追缘.mp3");
	Sleep(500);
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：独孤大哥，我们去看看段铁匠怎么样了吧？", 21);
	Say("独孤剑：好。", 1);
	SetNpcScript("段铁匠", "段铁匠尸体脚本.txt");
	SetNpcScript("张琳心", "张琳心对话.txt");
	Return;

scripts.周木匠对话.txt:
// 与周木匠的对话

	If ($Eventzhaoqi == 0) @Eventzhaoqi0;
	If ($Eventzhaoqi == 1) @Eventzhaoqi1;
	
@Eventzhaoqi0:

	If ($Talkmap016mujiang == 0) @Talk0;
	If ($Talkmap016mujiang == 1) @Talk1;
@Talk0:	
	Say("周木匠：问世间情为何物？是圆的还是方的？是铁做的还是棉花做的？是糖做的还是盐做的？你知不知道？唉……我一想起这问题就头痛。", 0);
	Assign("$Talkmap016mujiang", 1);
	Return;
@Talk1:	
	Say("周木匠：要是这问题象做家具那么简单就好了。", 0);
	Return;
	
	
@Eventzhaoqi1:	
	Say("周木匠：找我有什么事？是不是要做家具？", 0);
	Say("独孤剑：请问这位兄台，可曾婚配否？", 2);
	Say("周木匠：我俩素不相识，怎么突然问这么一个问题？", 0);
	Say("周木匠：唉，不瞒公子说，我正为这事发愁呢。我爹娘死的早，没人替我操心，眼看就要三十了，还没个家。", 0);
	Say("周木匠：你看我，也不是那种长相对不住观众的人，是不是？况且我还有一手好木匠手艺，虽说赶鲁班祖师爷还差点，但在当今临安城里也是数一数二了。我又不赌又不嫖，养活三两个人不成问题。",0);
	Say("周木匠：你说，天下那么多的女人，难道就没有一个是我的老婆？", 0);
	Say("独孤剑：兄台不必感叹了，你就是我要找的人。有一件美差，不知兄台是否愿意……", 2);
	Say("周木匠：现在除开老婆以外，没有其他什么事情对我来讲是美差。", 0);
	Say("独孤剑：在下要说的正是这种美差呀。有个……在下有个远房亲戚，年纪不过二十出头，就住在城西。她长得也还貌美，配兄台是有余了，就是守了三年寡……", 2);
	Say("周木匠：行，年轻貌美就行，听说寡妇更会疼人，我就想找个会疼人的老婆。再说，我这模样要找个黄花闺女恐怕也难了点……走吧，去瞧瞧，她在哪儿？", 0);
	Say("独孤剑：她住在靠近城西墙角的一座房子里，我还有点事，你先去看一看吧。", 2);
	Say("周木匠：好。", 0);
	
	SetPlayerDir(5);
	NpcGoto("周木匠", 18, 68);
	DelNpc("周木匠");
	SaveNpc();
	Assign($Eventzhaoqi, 2);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 255) @Event255;
	If ($Event == 256) @Event256;	//杀吕文才之后	

	Return;

@Event255:
	Say("张琳心：独孤大哥，我们去看看段铁匠怎么样了吧？", 21);	
	Return;

@Event256:
	Say("张琳心：不知家里到底发生了什么变故……", 28);
	Say("独孤剑：张姑娘，别着急，回去看看就知道了，你爹……他不会有事的！", 1);
	Say("张琳心：谢谢你，独孤大哥……", 28);
	Return;

scripts.段铁匠遇害.txt:
// 一进临安城遇见段铁匠遇害

	Say("张琳心：咦？前面怎么围了那么多人？", 25);
	Say("独孤剑：那不是吕文才吗？他带了许多士兵，不知又在干什么欺压百姓之事。", 1);
	Say("张琳心：我们过去看看吧。", 21);
	Sleep(500);
	PlayerGoto(7, 129);
	MoveScreen(5, 80, 3);
	Sleep(500);
	Say("吕文才：段老头，痛快点，说出你女儿和宝剑藏在什么地方吧，免得老子又把这破屋子再翻一遍！", 57);
	Say("段铁匠：哼！", 0);
	Say("吕文才：喂，你别敬酒不吃吃罚酒，你想想，我是当今秦相爷的表侄子，这张风一倒台，他那殿前都指挥使的位子不就是我的了？", 57);
	Say("到时候咱爷俩一文一武，这朝廷内外的事不就都是咱们一句话？你把你女儿嫁给我，把那宝剑作为陪嫁，你就是我的岳父大人了，你想要什么没有？要做官，给你个知府干干，如何？你要觉得做官麻烦，就买些良田美女，在家收贡，也很不错嘛，干吗就死脑筋，想不开呢？", 57);
	Say("段铁匠：呸，狗官！要杀就杀，要剐就剐，想我把女儿和宝剑给你这种狗官，没门！", 0);
	Say("吕文才：老混蛋！竟敢骂我，你找死！", 57);
	Say("段铁匠：落到你这个王八羔子手里，我就没打算活了！", 0);
	Say("吕文才：好！老子成全你！", 57);
	PlaySound("战_男攻04.wav");
	NpcSpecialAction("吕文才", "npc014_at.asf"); 
	Sleep(1000);
	PlaySound("战_男死01.wav");
	SetNpcActionFile("段铁匠", 0, "mpc012_3.asf");
	SetNpcActionFile("段铁匠", 1, "mpc012_3.asf");
	NpcSpecialAction("段铁匠", "mpc012_2.asf");
	Sleep(2000);
	DelNpc("段铁匠"); 	//对存盘的处理
	AddNpc("npc033_死亡段铁匠.ini", 15, 112, 7);
	SaveNpc();
	
	SetPlayerPos(9, 123);
	SetPlayerDir(5);
	Say("独孤剑：光天化日，竟敢在天子脚下草菅人命！", 5);
	Sleep(500);
	SetPlayerScn();
	SetNpcDir("吕文才", 2);
	PlayerGoto(15, 114);
	SetPlayerDir(6);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 14, 113);
	SetNpcDir("张琳心", 6);
		
	Say("吕文才：原来是你这小子！哈哈！老子在京城里杀几个人，如同踩死几只蚂蚁一样简单！上次我带的兵少，让你占了便宜，这次，哼哼，你可就没那么好运气了！来人哪，给我上！", 57);
	Say("张琳心：慢着！", 27);
	Say("吕文才：哦，原来是张姑娘，本将军正在到处找你呢，没想到你倒送上门来了！", 57);
	Say("张琳心：狗贼，你为什么要陷害我爹爹？", 27);
	Say("吕文才：哈，你去问你的爹爹呀！张姑娘你这么漂亮，本将军向来是怜香惜玉的，我就卖个人情告诉你算了！秦相爷的意思就是当今皇上的意思，你的爹爹偏偏又搞不懂相爷的意思，支持什么岳飞要打到黄龙府去把徽钦二帝接回来，违背了相爷的意思那他活着还有什么意思？", 57);
	Say("张琳心：奸贼！", 27);
	Say("吕文才：张姑娘，只要你跟了我，我保证你爹爹没事，好吗？", 57);
	Say("张琳心：无耻！", 27);
	Say("独孤剑：上次留你一条狗命，想不到你还敢为非作歹！", 5);
	SetNpcKind("张琳心", 3);
	
	FadeOut();
	StopMusic();
	PlayMusic("沙场.mp3");
	LoadNpc("map016_killlwc.npc"); 
	SetPlayerPos(15, 113);
	SetPlayerDir(5);
	SetNpcPos("张琳心", 16, 114);
	SetNpcDir("张琳心", 5);
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	Say("众百姓：哎呀，打起来啦，快跑呀！", 0);
	FadeIn();
	Say("吕文才：小子，爷爷上次的仇还没有报！咱们这次新仇旧恨一起算！", 57);
	SetNpcScript("吕文才", "");
	SetNpcRelation("吕文才", 1);
    SetNpcRelation("宋兵", 1);
    SetPlayerState(1);
    SetNpcScript("张琳心", "");
    EnableFight();
	EnableNpcAI(); 
	Assign($Event, 255);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap016jia == 0) @Talk0;
	If($Talkmap016jia == 1) @Talk1;
	If($Talkmap016jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap016jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap016jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.城东卫兵对话.txt:
// 城东卫兵对话

	If ($Event == 50) @Event5060; 
