	SetNpcPos("东门卫兵3", 0, 0);
	//SetNpcPos("东门卫兵4", 0, 0);
	Assign($Event, 80);
	Memo("出示令牌后，独孤剑出了东门，一路向东找寻采花贼的踪迹。");
