scripts.段铁匠尸体脚本.txt:
// 点击段铁匠尸体触发的脚本	
	
	//FadeOut();
	SetNpcKind("张琳心", 1);
	PlayerGoto(16, 114);
	SetPlayerDir(3);
	NpcGoto("张琳心", 15, 115);
	SetNpcDir("张琳心", 4);
	AddNpc("npc036_小叫化小雷.ini", 21, 104, 1);
	AddNpc("npc125_酒店掌柜.ini", 16, 121, 4);
	//FadeIn();
	
	SetNpcActionFile("独孤剑", 0, "mpc007_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc007_2.asf");
	NpcSpecialAction("独孤剑", "mpc007_1.asf");    // 独孤剑蹲下
	Sleep(1500);
	Say("独孤剑：段师傅！", 6);
	Say("段铁匠：我……我不行了，你们赶快走吧，官兵来了就走不掉了。我把小女芙蓉送到了海边渔村她外公老王家，麻烦你们二位将她送到成都她姑妈家……这里有几颗烟火霹雳弹，你们拿去用吧……", 0);
	Say("独孤剑：段师傅！段师傅！", 6);
	Say("张琳心：他已经死了。", 26);
	AddGoods("Goods061_烟火霹雳弹.ini"); 
	AddGoods("Goods061_烟火霹雳弹.ini");
	AddGoods("Goods061_烟火霹雳弹.ini");
	AddMagic("magic056_烟火霹雳弹.ini", 1);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc007_3.asf");    // 独孤剑站起	
	Sleep(1500);
	
	Say("酒店掌柜：独孤大侠！", 85);
	SetPlayerDir(0);
	SetNpcDir("张琳心", 0);
	NpcGoto("酒店掌柜", 16, 115);
	SetNpcDir("酒店掌柜", 3);
	SetPlayerDir(7);
	SetNpcDir("张琳心", 6);
	Say("酒店掌柜：多谢独孤大侠和张姑娘，替我们临安城的老百姓去除了一害！只是段铁匠死的好惨！", 85);
	Say("张琳心：那段铁匠是一个老实人，怎么会招惹上吕文才的呢？", 21);
	SetNpcDir("酒店掌柜", 2);
	Say("酒店掌柜：唉！那吕文才还不是看上了段铁匠的两样宝贝！他为了霸占段家女儿和段铁匠收藏的一把宝剑，竟然诬赖段铁匠是张大人的同谋，也是金国派来的奸细，不分青红皂白就把段铁匠给抓了起来。", 85);
	Say("酒店掌柜：好在段铁匠早就得到风声，让他的女儿带着宝剑躲出去了，要不就真的栽到姓吕的手里了。", 85);
	Say("张琳心：啊？！我爹怎么啦？", 25);
	Say("酒店掌柜：原来张姑娘还不知道啊，你爹被革职查办了！秦相爷说他是金国奸细，派出亲信正在到处抓他呢。你家也被抄了，现在府上全是秦相爷的人，张姑娘你可千万别回去呀！", 85);
	Say("张琳心：啊？！……", 26);
	SetNpcDir("酒店掌柜", 3);
	Say("酒店掌柜：你们二位杀了吕文才，这祸可闯大了，秦相爷肯定不会善罢甘休，你们还是赶快离开临安吧！", 85);
	Say("酒店掌柜：那吕文才见我酒馆生意好，想夺我的店，现在这狗官一死，这酒店又是我的了，真该好好谢谢你们。我这里有一副兽骨项圈和几坛好酒，送给二位表示一下老汉的心意。", 85);
	Say("独孤剑：您太客气了……", 2);
	Say("酒店掌柜：你们就不要推辞了，还是快些逃出城去吧，免得被官兵抓到。待会官兵肯定会满城抓人，我也要回去打烊了。", 85);
	Say("独孤剑：多谢您！", 2);
	AddGoods("Goods014_兽骨项圈.ini");
	Sleep(500);
	AddGoods("Goods207_十年佳酿.ini"); 
	AddGoods("Goods207_十年佳酿.ini"); 
	AddGoods("Goods207_十年佳酿.ini"); 
	AddGoods("Goods207_十年佳酿.ini"); 
	AddGoods("Goods207_十年佳酿.ini"); 
	
